120	// Do performs an HTTP request to the downstream service.
121	//
122	// ctx:     required context. Cancelation/timeout is respected.
123	// method:  HTTP method (GET, POST, ...).
124	// path:    relative path appended to baseURL. Leading slash optional.
125	// body:    request body, may be nil.
126	// hdr:     additional headers merged with defaultHeaders.
127	func (c *HTTPClient) Do(
128		ctx context.Context,
129		method, path string,
130		body io.Reader,
131		hdr http.Header,
132	) (*http.Response, error) {
133		if ctx == nil {
134			return nil, errors.New("ctx must not be nil")
135		}
136	
137		start := time.Now()
138		var resp *http.Response
139		var err error
140	
141		// Convert relative path to full URL.
142		url := joinURL(c.baseURL, path)
143	
144		mergedHdr := c.cloneDefaultHeaders()
145		for k, vs := range hdr {
146			for _, v := range vs {
147				mergedHdr.Add(k, v)
148			}
149		}
150	
151		// Obtain auth token if required.
152		if c.authProvider != nil && mergedHdr.Get("Authorization") == "" {
153			tok, tokErr := c.authProvider.Token(ctx)
154			if tokErr != nil {
155				return nil, tokErr
156			}
157			mergedHdr.Set("Authorization", "Bearer "+tok)
158		}
159	
160		reqBody, err := readBody(body)
161		if err != nil {
162			return nil, err
163		}
164	
165		operation := func() (any, error) {
166			// Rewind the body on every retry attempt.
167			reader := bytes.NewReader(reqBody)
168	
169			req, rErr := http.NewRequestWithContext(ctx, method, url, reader)
170			if rErr != nil {
171				return nil, rErr
172			}
173			req.Header = mergedHdr
174	
175			// Inject tracing.
176			ctx, span := c.tracer.Start(ctx, method+" "+path,
177				trace.WithAttributes(attribute.String("http.method", method)))
178			defer span.End()
179	
180			r, dErr := c.httpClient.Do(req)
181			if dErr != nil {
182				span.RecordError(dErr)
183				return nil, dErr
184			}
185			return r, nil
186		}
187	
188		for i := 0; i <= c.retryCount; i++ {
189			var result any
190			result, err = c.breaker.Execute(operation)
191			if err == nil {
192				resp = result.(*http.Response)
193				break
194			}
195	
196			// Only retry on transient network errors or 5xx responses.
197			if !shouldRetry(err) && !isRetryableHTTP(resp) {
198				break
199			}
200	
201			sleep := backoff(i)
202			c.logger.Warn().
203				Err(err).
204				Int("attempt", i+1).
205				Str("url", url).
206				Dur("sleep", sleep).
207				Msg("retrying downstream call")
208	
209			select {
210			case <-time.After(sleep):
211			case <-ctx.Done():
212				return nil, ctx.Err()
213			}
214		}
215	
216		// Observe metrics.
217		c.metrics.observe(method, resp, start)
218	
219		if err != nil {
220			c.logger.Error().Err(err).
221				Str("method", method).
222				Str("url", url).
223				Msg("downstream request failed")
224		}
225	
226		return resp, err
227	}
