229	// PostJSON marshals payload as JSON and POSTs it with Content-Type: application/json.
230	func (c *HTTPClient) PostJSON(
231		ctx context.Context,
232		path string,
233		payload any,
234		response any,
235	) error {
236		buf := bytes.Buffer{}
237		if err := json.NewEncoder(&buf).Encode(payload); err != nil {
238			return err
239		}
240		h := http.Header{}
241		h.Set("Content-Type", "application/json")
242		resp, err := c.Do(ctx, http.MethodPost, path, &buf, h)
243		if err != nil {
244			return err
245		}
246		defer resp.Body.Close()
247	
248		if resp.StatusCode >= 400 {
249			return parseDownstreamError(resp)
250		}
251		if response != nil {
252			return json.NewDecoder(resp.Body).Decode(response)
253		}
254		return nil
255	}
