257	// helper: join baseURL and path.
258	func joinURL(base, path string) string {
259		switch {
260		case path == "":
261			return base
262		case base[len(base)-1] == '/' && path[0] == '/':
263			return base + path[1:]
264		case base[len(base)-1] != '/' && path[0] != '/':
265			return base + "/" + path
266		default:
267			return base + path
268		}
269	}
