271	// helper: clone default headers to avoid race-conditions.
272	func (c *HTTPClient) cloneDefaultHeaders() http.Header {
273		dup := make(http.Header, len(c.defaultHeaders))
274		for k, v := range c.defaultHeaders {
275			vv := make([]string, len(v))
276			copy(vv, v)
277			dup[k] = vv
278		}
279		return dup
280	}
