290	// shouldRetry determines if err is retriable.
291	func shouldRetry(err error) bool {
292		if err == nil {
293			return false
294		}
295		var netErr net.Error
296		if errors.As(err, &netErr) && netErr.Temporary() {
297			return true
298		}
299		return false
300	}
301	
302	// isRetryableHTTP returns true if response is 5xx.
303	func isRetryableHTTP(resp *http.Response) bool {
304		if resp == nil {
305			return false
306		}
307		return resp.StatusCode >= 500
308	}
309	
310	// backoff returns exponential backoff with jitter.
311	func backoff(attempt int) time.Duration {
312		if attempt == 0 {
313			return 0
314		}
315		base := time.Duration(1<<uint(attempt)) * 100 * time.Millisecond
316		// Apply jitter.
317		return base + time.Duration(int64(base)/3)
318	}
