320	// parseDownstreamError converts non-2xx HTTP responses into internal error.
321	func parseDownstreamError(resp *http.Response) error {
322		b, _ := io.ReadAll(io.LimitReader(resp.Body, 8<<10)) // 8 KiB
323		return errors.New(resp.Status + ": " + string(b))
324	}
