374	func (m *clientMetrics) observe(method string, resp *http.Response, start time.Time) {
375		status := "error"
376		if resp != nil {
377			status = http.StatusText(resp.StatusCode)
378		}
379		// Response may be nil on network error, so status might be "error".
380		m.latency.WithLabelValues(respService(resp), method, status).
381			Observe(time.Since(start).Seconds())
382	
383		if status == "error" || (resp != nil && resp.StatusCode >= 500) {
384			m.errors.WithLabelValues(respService(resp), method).Inc()
385		}
386	}
