1	// Package middleware contains HTTP middleware components used by the
2	// ScholarPass API-Gateway.  This file implements a Redis-backed response-cache
3	// that accelerates repeated read-only requests such as curriculum look-ups.
4	//
5	// Typical usage:
6	//
7	//	redisClient := redis.NewClient(&redis.Options{Addr: cfg.RedisURL})
8	//	cacheMw     := middleware.NewCacheMiddleware(redisClient,
9	//		middleware.WithTTL(10*time.Minute))
10	//
11	//	r := chi.NewRouter()
12	//	r.With(cacheMw.Handler).Get("/v1/curriculum/{id}", curriculumHandler)
13	package middleware
14	
15	import (
16		"bytes"
17		"context"
18		"crypto/sha1" // #nosec G505 -- SHA-1 used only for non-security ETag hashing.
19		"encoding/json"
20		"fmt"
21		"io"
22		"net/http"
23		"strings"
24		"time"
25	
26		"github.com/redis/go-redis/v9"
27		"golang.org/x/sync/singleflight"
28	)
29	
30	// ----------------------------------------------------------------------------
31	// Public configuration options
32	// ----------------------------------------------------------------------------
33	
34	// KeyFunc generates a cache key for a given request.
35	type KeyFunc func(r *http.Request) (string, error)
36	
37	// CacheOption mutates middleware configuration.
38	type CacheOption func(*CacheMiddleware)
39	
40	// WithTTL sets the global default TTL for cached objects. Defaults to
41	// 5 minutes.
42	func WithTTL(ttl time.Duration) CacheOption {
43		return func(m *CacheMiddleware) { m.ttl = ttl }
44	}
45	
46	// WithKeyFunc replaces the default cache key generator.
47	func WithKeyFunc(fn KeyFunc) CacheOption {
48		return func(m *CacheMiddleware) { m.keyFunc = fn }
49	}
50	
51	// WithMethods configures the list of HTTP methods that are eligible for
52	// caching.  By default only GET and HEAD are cached.
53	func WithMethods(methods ...string) CacheOption {
54		return func(m *CacheMiddleware) {
55			m.cacheableMethods = make(map[string]struct{}, len(methods))
56			for _, mtd := range methods {
57				m.cacheableMethods[strings.ToUpper(mtd)] = struct{}{}
58			}
59		}
60	}
61	
62	// WithMaxBodySize limits the maximum size (in bytes) of a response that can be
63	// cached.  If set to 0 there is no limit.  Defaults to 1 MiB.
64	func WithMaxBodySize(maxBytes int) CacheOption {
65		return func(m *CacheMiddleware) { m.maxBodySize = maxBytes }
66	}
67	
68	// ----------------------------------------------------------------------------
69	// Cache middleware implementation
70	// ----------------------------------------------------------------------------
71	
72	// CacheMiddleware is an HTTP middleware that stores successful responses in
73	// Redis and serves subsequent requests directly from the cache.
74	type CacheMiddleware struct {
75		redisClient      *redis.Client
76		ttl              time.Duration
77		keyFunc          KeyFunc
78		cacheableMethods map[string]struct{}
79		maxBodySize      int
80		group            singleflight.Group
81	}
82	
83	// NewCacheMiddleware builds a cache middleware backed by the provided Redis
84	// client.
85	func NewCacheMiddleware(redisClient *redis.Client, opts ...CacheOption) *CacheMiddleware {
86		m := &CacheMiddleware{
87			redisClient: redisClient,
88			ttl:         5 * time.Minute,
89			keyFunc:     defaultKeyFunc,
90			cacheableMethods: map[string]struct{}{
91				http.MethodGet:  {},
92				http.MethodHead: {},
93			},
94			maxBodySize: 1 << 20, // 1 MiB
95		}
96		for _, o := range opts {
97			o(m)
98		}
99		return m
100	}
101	
102	// Handler returns the actual middleware function that can be plugged into an
103	// HTTP router such as chi or gin.
104	func (m *CacheMiddleware) Handler(next http.Handler) http.Handler {
105		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
106			// Skip non-cacheable request methods early.
107			if _, ok := m.cacheableMethods[r.Method]; !ok {
108				next.ServeHTTP(w, r)
109				return
110			}
111	
112			// Respect explicit client instructions to skip cache.
113			if cc := r.Header.Get("Cache-Control"); cc != "" && strings.Contains(cc, "no-cache") {
114				next.ServeHTTP(w, r)
115				return
116			}
117	
118			ctx := r.Context()
119	
120			// Compute the cache key.
121			key, err := m.keyFunc(r)
122			if err != nil {
123				// If key generation fails we fall back to a passthrough.
124				next.ServeHTTP(w, r)
125				return
126			}
127	
128			// Fast path—see if the item is already cached.
129			if cached, ok := m.getCachedResponse(ctx, key); ok {
130				m.serveCached(w, r, cached)
131				return
132			}
133	
134			// Prevent cache stampede; only one goroutine hits the origin per key.
135			// Others will wait for the first to finish and then read from Redis.
136			_, err, _ = m.group.Do(key, func() (interface{}, error) {
137				// Double-check cache in case it was populated while we were waiting.
138				if c, ok := m.getCachedResponse(ctx, key); ok {
139					m.serveCached(w, r, c)
140					return nil, nil // No error; we already responded.
141				}
142	
143				// Capture the origin response.
144				rec := newResponseRecorder(w, m.maxBodySize)
145				next.ServeHTTP(rec, r)
146	
147				// Store if the response is cacheable.
148				if rec.status == http.StatusOK && rec.size <= m.maxBodySize {
149					etag := computeETag(rec.body.Bytes())
150					rec.Header().Set("ETag", etag)
151					_ = m.storeCachedResponse(ctx, key, rec, etag)
152				}
153				// Ensure the recorded response is flushed to the client.
154				rec.flush()
155				return nil, nil
156			})
157			// group.Do already responded to the client.
158			if err != nil {
159				// Should never happen, but just in case.
160				http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
161			}
162		})
163	}
