165	// ----------------------------------------------------------------------------
166	// Internal helpers
167	// ----------------------------------------------------------------------------
168	
169	type cachedResponse struct {
170		Status int         `json:"status"`
171		Header http.Header `json:"header"`
172		Body   []byte      `json:"body"`
173		ETag   string      `json:"etag,omitempty"`
174	}
175	
176	func (m *CacheMiddleware) getCachedResponse(ctx context.Context, key string) (*cachedResponse, bool) {
177		raw, err := m.redisClient.Get(ctx, key).Bytes()
178		if err == redis.Nil || err != nil {
179			return nil, false
180		}
181		var cr cachedResponse
182		if jsonErr := json.Unmarshal(raw, &cr); jsonErr != nil {
183			// On deserialization failure, invalidate the key to avoid poisoning.
184			_ = m.redisClient.Del(ctx, key).Err()
185			return nil, false
186		}
187		return &cr, true
188	}
189	
190	func (m *CacheMiddleware) storeCachedResponse(ctx context.Context, key string, rec *responseRecorder, etag string) error {
191		cr := cachedResponse{
192			Status: rec.status,
193			Header: rec.Header().Clone(),
194			Body:   rec.body.Bytes(),
195			ETag:   etag,
196		}
197		// Ensure Content-Length is correct for the cached body (some handlers
198		// might rely on implicit chunked encoding).
199		cr.Header.Set("Content-Length", fmt.Sprintf("%d", len(cr.Body)))
200	
201		data, err := json.Marshal(cr)
202		if err != nil {
203			return err
204		}
205		return m.redisClient.Set(ctx, key, data, m.ttl).Err()
206	}
207	
208	func (m *CacheMiddleware) serveCached(w http.ResponseWriter, r *http.Request, cr *cachedResponse) {
209		// Handle conditional requests using ETag.
210		if inm := r.Header.Get("If-None-Match"); inm != "" && inm == cr.ETag {
211			w.WriteHeader(http.StatusNotModified)
212			return
213		}
214	
215		for k, vals := range cr.Header {
216			for _, v := range vals {
217				w.Header().Add(k, v)
218			}
219		}
220		w.Header().Set("X-Cache", "HIT")
221		w.WriteHeader(cr.Status)
222		_, _ = w.Write(cr.Body)
223	}
