225	// defaultKeyFunc generates a cache key that is aware of the HTTP method, host,
226	// path, query string, and tenant scope (if present via X-Tenant-ID header or
227	// JWT claims decoded by upstream auth middleware).
228	func defaultKeyFunc(r *http.Request) (string, error) {
229		tenantID := r.Header.Get("X-Tenant-ID")
230		if tenantID == "" {
231			tenantID = "global"
232		}
233		// We deliberately ignore headers such as Accept-Encoding because responses
234		// are served uncompressed (gateway handles compression separately).
235		return fmt.Sprintf("scholarpass:gateway:v1:cache:%s:%s:%s?%s",
236			tenantID, r.Method, r.URL.Path, r.URL.RawQuery), nil
237	}
