248	
249	// responseRecorder captures the origin handler's response so we can both cache
250	// it and re-emit it to the client.
251	type responseRecorder struct {
252		http.ResponseWriter
253		status int
254		body   *bytes.Buffer
255		size   int
256		limit  int
257	}
258	
259	func newResponseRecorder(w http.ResponseWriter, limit int) *responseRecorder {
260		return &responseRecorder{
261			ResponseWriter: w,
262			status:         http.StatusOK,
263			body:           &bytes.Buffer{},
264			limit:          limit,
265		}
266	}
267	
268	func (r *responseRecorder) Header() http.Header {
269		return r.ResponseWriter.Header()
270	}
271	
272	func (r *responseRecorder) WriteHeader(code int) {
273		r.status = code
274		// Defer writing headers until flush() to ensure we can set ETag, etc.
275	}
276	
277	func (r *responseRecorder) Write(b []byte) (int, error) {
278		if r.limit == 0 || r.size+len(b) <= r.limit {
279			if _, err := r.body.Write(b); err != nil {
280				return 0, err
281			}
282		}
283		r.size += len(b)
284		return len(b), nil
285	}
