287	// flush writes the recorded headers/body to the underlying ResponseWriter.
288	func (r *responseRecorder) flush() {
289		// Ensure headers are written.
290		// Some handlers might have already called WriteHeader manually; if not,
291		// WriteHeader with stored status.
