51	// NewSchemaLoader instantiates a new loader. When hotReload is true, schema files
52	// are watched for changes and automatically re-compiled.
53	func NewSchemaLoader(root string, hotReload bool) (*SchemaLoader, error) {
54		root = filepath.Clean(root)
55		if stat, err := os.Stat(root); err != nil || !stat.IsDir() {
56			return nil, fmt.Errorf("schema loader: root directory %q is invalid: %w", root, err)
57		}
58	
59		loader := &SchemaLoader{
60			root:        root,
61			jsonSchemas: make(map[string]*jsonSchemaEntry),
62			gqlSchemas:  make(map[string]*gqlSchemaEntry),
63		}
64	
65		if hotReload {
66			w, err := fsnotify.NewWatcher()
67			if err != nil {
68				return nil, fmt.Errorf("schema loader: cannot create fs watcher: %w", err)
69			}
70			loader.watcher = w
71			loader.ctx, loader.cancel = context.WithCancel(context.Background())
72	
73			// Watch all sub-directories under root.
74			if err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
75				if err != nil {
76					return err
77				}
78				if d.IsDir() {
79					return loader.watcher.Add(path)
80				}
81				return nil
82			}); err != nil {
83				_ = w.Close()
84				return nil, fmt.Errorf("schema loader: failed to register directories: %w", err)
85			}
86	
87			go loader.watchLoop()
88		}
89	
90		return loader, nil
91	}
