167	func (l *SchemaLoader) compileJSONSchema(version, name string) (*gojsonschema.Schema, time.Time, error) {
168		path := l.jsonPath(version, name)
169		stat, err := os.Stat(path)
170		if err != nil {
171			return nil, time.Time{}, fmt.Errorf("schema loader: stat %s: %w", path, err)
172		}
