174		uri := "file://" + filepath.ToSlash(path)
175		compiled, err := gojsonschema.NewSchema(gojsonschema.NewReferenceLoader(uri))
176		if err != nil {
177			return nil, time.Time{}, fmt.Errorf("schema loader: compile %s: %w", path, err)
178		}
