183	func (l *SchemaLoader) compileGraphQLSchema(version, name string) (*ast.Schema, time.Time, error) {
184		path := l.gqlPath(version, name)
185		stat, err := os.Stat(path)
186		if err != nil {
187			return nil, time.Time{}, fmt.Errorf("schema loader: stat %s: %w", path, err)
188		}
