190		raw, err := os.ReadFile(path)
191		if err != nil {
192			return nil, time.Time{}, fmt.Errorf("schema loader: read %s: %w", path, err)
193		}
194	
195		doc, parseErr := gqlparser.LoadSchema(&ast.Source{
196			Name:  filepath.Base(path),
