293	func (l *SchemaLoader) watchLoop() {
294		for {
295			select {
296			case <-l.ctx.Done():
297				return
298	
299			case ev, ok := <-l.watcher.Events:
300				if !ok {
301					return
302				}
303	
304				if ev.Op&(fsnotify.Write|fsnotify.Create|fsnotify.Remove|fsnotify.Rename) != 0 {
305					// Purge all caches—schemas are inexpensive to re-compile and this
306					// keeps bookkeeping simple.
307					l.purgeCaches()
308				}
309	
310			case err, ok := <-l.watcher.Errors:
311				if ok {
312					log.Printf("schema loader: fsnotify error: %v", err)
313				}
314			}
315		}
316	}
